	/*master.mdcm.updateMasterMdCmStndCatalogConfirm*/

             UPDATE CMSCATLG A  
                SET A.STATUS = #{STATUS}
                , A.CHANGE_DATE =  TO_CHAR(SYSDATE,'YYYYMMDD')
                , A.CHANGE_TIME =  TO_CHAR(SYSDATE,'HH24MISS')
                , A.CHANGE_USER_ID = #{USR_ID}
               WHERE A.CMS_CATLG_ID = #{CMS_CATLG_ID}
